function checkRangeData(objField,sFieldName,minValue,maxValue){if(!isValidRange(objField.value,minValue,maxValue)){return getFocusAlert(objField,"You must enter a valid number for "+sFieldName+" between "+minValue+" and "+maxValue+".")}else{return true}}function checkNumberData(objField,sFieldName){if(!isValidNumber(objField.value)){return getFocusAlert(objField,"You must enter a valid number for "+sFieldName+".")}else{return true}}function checkNumberDataNotReq(objField,sFieldName){if(!isValidNumber(objField.value)&&objField.value!=''){return errorAlert("You must enter a valid number for "+sFieldName+".")}else{return true}}function checkStringData(objField,sFieldName){if(!isValidString(objField.value)){return getFocusAlert(objField,"You must enter a valid value for "+sFieldName+".")}else{return true}}function checkLengthData(objField,sFieldName,maxLength){if(!isValidLength(objField.value,maxLength)){return getFocusAlert(objField,"You cannot enter more than "+maxLength+" characters for "+sFieldName+".")}else{return true}}function checkPhoneData(objField,sFieldName){var result=false;if(isValidString(objField.value)){var stripped=objField.value.replace(/[x\(\)\.\-\ ]/g,'');if(stripped.length>=10){if(!isNaN(stripped)){result=true}}}if(result==false){return getFocusAlert(objField,"You must enter a valid value for "+sFieldName+".")}return result}function checkZipcodeData(objField,sFieldName){if(!isValidZipcode(objField.value)){return getFocusAlert(objField,"You must enter a valid value for "+sFieldName+".")}else{return true}}function checkTextData(objField,sFieldName){if(!isValidString(objField.value)||!isNaN(objField.value)){return getFocusAlert(objField,"You must enter a valid value for "+sFieldName+".")}else{return true}}function checkFileName(objField,sFieldName,sFileExtension){if(!isValidFile(objField.value,sFileExtension)){var sMsg="You must enter a valid file name for "+sFieldName+" that does not contain spaces or the characers \\/\':*?\"<>[]{}|";if(isValidText(sFileExtension)){sMsg=sMsg+" and ends with the extension '"+sFileExtension+"'"}sMsg=sMsg+".";return getFocusAlert(objField,sMsg)}else{return true}}function checkSelectData(objField,sFieldName,invalidValue){if(!isValidSelectionValue(objField,invalidValue)){return getFocusAlert(objField,"You must select a valid value for "+sFieldName+".")}else{return true}}function checkEmailData(objField,sFieldName){if(!isValidEmail(objField.value)){return getFocusAlert(objField,"You must enter a valid value for "+sFieldName+".")}else{return true}}function checkCheckboxData(objField,sFieldName){if(!isChecked(objField)){return getFocusAlert(objField,"You must check "+sFieldName+".")}else{return true}}function checkRadioData(objField,sMsg){return checkObjectArrayData(objField,sMsg)}function checkObjectArrayData(objField,sMsg){var result=getObjectArrayCheckedIndex(objField);if(isNaN(result)&&objField.checked==false){return getFocusAlert(objField,sMsg)}else if(result==-1){objField[0].focus();return errorAlert(sMsg)}else{return true}}function getFocusAlert(objField,sMsg){objField.focus();return errorAlert(sMsg)}function errorAlert(sMsg){alert(sMsg);return false}function getRadioValue(objField){var result=null;var checkedIndex=getCheckedIndex(objField);if(isNaN(checkedIndex)){result=objField.value}else{result=objField[checkedIndex].value}return result}function getCheckedIndex(objField){return getObjectArrayCheckedIndex(objField)}function getObjectArrayLength(objField){var result="only one element";if(!isNaN(objField.length)){result=objField.length}return result}function getObjectArrayCheckedIndex(objField){var length=getObjectArrayLength(objField);var checkedIndex=-1;if(isNaN(length)){checkedIndex="Not Checked"}else{for(var i=0;i<length;i++){if(objField[i].checked){checkedIndex=i;break}}}return checkedIndex}function isValidString(StringValue){var result=false;if((StringValue!=null)&&(StringValue.length>0)){result=true}return result}function isValidText(StringValue){var result=false;if((isValidString(StringValue))&&(isNaN(StringValue))){result=true}return result}function isAlphabetic(StringValue){var result=false;if((isValidString(StringValue))&&(StringValue.search(/[^a-zA-Z]/g)==-1)){result=true}return result}function isValidLength(StringValue,maxLength){var result=false;if(StringValue.length<=maxLength){result=true}return result}function isValidNumber(StringValue){var result=false;if((isValidString(StringValue))&&(!isNaN(StringValue))){result=true}return result}function isValidRange(StringValue,minValue,maxValue){var result=false;if(isValidNumber(StringValue)){if((StringValue<=maxValue)&&(StringValue>=minValue)){result=true}}return result}function isValidSelectionValue(objField,invalidValue){var result=false;if(objField.options[objField.options.selectedIndex].value!=invalidValue){result=true}return result}function isValidSelectionIndex(objField,invalidIndex){var result=false;if(objField.selectedIndex!=invalidIndex){result=true}return result}function isValidFile(sFileName,sFileExtension){sFileName=sFileName.toLowerCase();sFileExtension=sFileExtension.toLowerCase();var result=false;if(isValidText(sFileName)){if(sFileName.search(/[\\\/\:\*\?\<\>\|\s\"\'\{\}\[\]]/g)==-1){if(isValidText(sFileExtension)){if(sFileName.indexOf(sFileExtension)>0){result=true}}else{result=true}}}return result}function isValidEmail(email){var result=false;if(isValidString(email)){var theStr=new String(email);var index=theStr.indexOf("@");if(index>0){var pindex=theStr.indexOf(".",index);if((pindex>index+1)&&(theStr.length>pindex+2)){result=true}}}return result}function isValidDate(day,month,year){day=""+parseInt(day,10);month=""+parseInt(month,10);year=""+parseInt(year,10);if(!isValidRange(month,1,12)){return false}if(!isValidRange(day,1,31)){return false}if((month==4||month==6||month==9||month==11)&&day==31){return false}if(month==2){var isleap=(year%4==0&&(year%100!=0||year%400==0));if(day>29||(day==29&&!isleap)){return false}}return true}function isFutureDate(day,month,year){day=""+parseInt(day);month=""+parseInt(month);year=""+parseInt(year);if(!isValidDate(day,month,year)){return false}var currentDate=new Date();var testDate=new Date(year,month-1,day);if(currentDate.getFullYear()>testDate.getFullYear()){return false}else if(currentDate.getFullYear()==testDate.getFullYear()){if(currentDate.getMonth()>testDate.getMonth()){return false}else if(currentDate.getMonth()==testDate.getMonth()){if(currentDate.getDate()>=testDate.getDate()){return false}}}return true}function setDefaultValue(objField,sDefaultVal){if(!isValidString(objField.value)){objField.value=sDefaultVal}}function isChecked(objField){var result=false;if(objField.checked==true){result=true}return result}function setCheckValue(objField,checkedValue,uncheckedValue){if(objField.checked==true){objField.value=checkedValue}else{objField.value=uncheckedValue}}function cleanNumberic(strNumeric){return strNumeric.replace(/\D/g,'')}function checkCardNumWithMod10(cardNum){var i;var cc=new Array(16);var checksum=0;var validcc;for(i=0;i<cardNum.length;i++){cc[i]=Math.floor(cardNum.substring(i,i+1))}for(i=(cardNum.length%2);i<cardNum.length;i+=2){var a=cc[i]*2;if(a>=10){var aStr=a.toString();var b=aStr.substring(0,1);var c=aStr.substring(1,2);cc[i]=Math.floor(b)+Math.floor(c)}else{cc[i]=a}}for(i=0;i<cardNum.length;i++){checksum+=Math.floor(cc[i])}validcc=((checksum%10)==0);return validcc}function isValidCCNum(cardNum,cardType){var upperCardType=cardType.toUpperCase();var result=false;var cardLen=cardNum.length;var firstdig=cardNum.substring(0,1);var seconddig=cardNum.substring(1,2);var first4digs=cardNum.substring(0,4);switch(upperCardType){case"VISA":result=((cardLen==16)||(cardLen==13))&&(firstdig=="4");break;case"AMEX":var validNums="47";result=(cardLen==15)&&(firstdig=="3")&&(validNums.indexOf(seconddig)>=0);break;case"MSTR":var validNums="12345";result=(cardLen==16)&&(firstdig=="5")&&(validNums.indexOf(seconddig)>=0);break;case"DISC":result=(cardLen==16)&&(first4digs=="6011");break;default:return errorAlert(cardType+" is not a recognized credit card type");break}return result}function checkCCData(objField,sFieldName,sCardType){if(isValidString(objField.value)){sCardNum=objField.value;sCardNum=sCardNum.replace(/[-\s]/g,'')}else{return getFocusAlert(objField,"You must enter a valid value for "+sFieldName+".")}if(isNaN(sCardNum)||(!isValidCCNum(sCardNum,sCardType))){return getFocusAlert(objField,"You must enter a valid value for "+sFieldName+".")}else{objField.value=sCardNum;return true}}function isValidZipcode(strZipCode){var result=false;if(isValidString(strZipCode)){var objRegExp=/(^\d{5}$)|(^\d{5}-\d{4}$)/;result=objRegExp.test(strZipCode)}return result}function textAreaMaxLength(textObj,len){if(textObj.value.length>len){alert('Only a maximum of '+len+' characters allowed');textObj.value=textObj.value.substring(0,len);return false}return true}